import json, pathlib
ship = "8bad21f7f11d254b853ff2436194774215a7f2fb"
commits = {}
for p in pathlib.Path('.gitreins/history').rglob('verdict.json'):
    try: d = json.loads(p.read_text(encoding='utf-8', errors='replace'))
    except Exception: continue
    if isinstance(d, dict) and d.get('task_id') == 'INT-GL-3':
        commits.setdefault(d.get('commit'), []).append(str(p))
for c, paths in commits.items():
    print('commit:', c, '==' , 'SHIPPED-TIP' if c==ship else 'NOT shipped tip', 'files:', len(paths))
board = None
for line in open('.coding-hermes/board/tasks.jsonl', encoding='utf-8'):
    line=line.strip()
    if not line: continue
    try: row=json.loads(line)
    except Exception: continue
    if isinstance(row,dict) and row.get('id')=='INT-GL-3':
        board = row.get('commit_hash')
print('board INT-GL-3 commit_hash:', repr(board))
EOF
